           storage: {
             type: 'cookie'
@@ -1485,4 +1494,191 @@ describe('User ID', function() {
       expect(coreStorage.setCookie.getCall(0).args[4]).to.equal(null);
     });
   });
+
+  describe('Consent changes determine getId refreshes', function() {
+    const mockIdCookieName = 'MOCKID';
+    let expStr;
+    let adUnits;
+    let mockGetId = sinon.stub();
+    let mockDecode = sinon.stub();
+    let mockExtendId = sinon.stub();
+    let cmpStub;
+    let testConsentData;
+    const consentConfig = {
+      cmpApi: 'iab',
+      timeout: 7500,
+      allowAuctionWithoutConsent: false
+    };
+    const userIdConfig = {
+      userSync: {
+        userIds: [{
+          name: 'mockId',
+          storage: {
+            name: 'MOCKID',
+            type: 'cookie',
+            refreshInSeconds: 30
