+        args[2](testConsentData);
+      });
+      setConsentConfig(consentConfig);
+    });
+
+    afterEach(function () {
+      config.resetConfig();
+      mockGetId.reset();
+      mockDecode.reset();
+      mockExtendId.reset();
+      delete window.__cmp;
+      cmpStub.restore();
+      resetConsentData();
+    });
+
+    it('does not call getId if no stored consent data and refresh is not needed', function () {
